INSERT INTO `andrew_test` VALUES (1,'andrewm_temco','hosting account, or choose \"Add A Domain Name\", to register a new domain name (if you have free domain credits, you can register a domain for free). This will open a new window. \r\nYou will arrive at the pre-filled order form. Provide your preferred payment method, if you want to use your free domain credits for registering a domain, simply choose \"Pay With Domain Points\" as payment method. That option will only be available if you have unused domain credits. \r\n','61.171.253.4','2007-12-03 09:56:59'),(2,'xxdsa okokok','µÚÒ»½ìÅ·ÖÞ±­£¬Î÷°àÑÀÊ×ÂÖ7-2ÌÔÌ­²¨À¼£¬µ«´ÎÂÖÓöµ½ËÕÁª£¬ÓÉÓÚÕþÖÎÔ­Òò£¬¶À²ÃÕß·ðÀÊ¸çÊ§ÎóÓÒÒíÕþ¸®ÀÕÁîÎ÷°àÑÀ¶ÓÍË³ö±ÈÈü£¬½á¹ûËÕÁª¶Ó²»Õ½¶øÊ¤£¬×îºó³É¹¦µÇ¶¥¡£\r\n\r\nÉÏÊÀ¼Í80Äê´úÇ°£¬Å·ÖÞ±­»¹²»ÊÇÈü»áÖÆ£¬Ö÷¿Í³¡½»·æ¶Ô±ÈÈüÓ°ÏìÆÄ´ó£¬µ¥³¡ÌÔÌ­Èü³¡µØÓÉ³éÇ©¾ö¶¨¡£1964ÄêÎ÷°àÑÀ¾Í°ÑÎÕ×¡ÁË»ú»á£¬Ò»¾ÙÎÊ¶¦ËûÃÇÖÁ½ñÎ¨Ò»µÄ³ÉÄê¹ú¼Ò¶Ó´óÈü¹Ú¾ü£¨°ÂÔË»áÄÐ×ã²»Ëã£©¡£\r\n\r\nµ±ÄêÎ÷°àÑÀ¶ÓÊ×Õ½1-1±»±±°®¶ûÀ¼±ÆÆ½£¬Ó¢¸ñÀ¼¼®Ö÷Ë§»ôÀ¼ÕÙ»ØÔÚº£ÍâÐ§Á¦µÄ´óÅÆÇòÐÇ£¬×îºóÔÚ±´¶û·¨Ë¹ÌØ1-0»÷°Ü±±°®¡£´ÎÂÖÁ½»ØºÏ7-1ºáÉ¨°®¶ûÀ¼£¬°ë¾öÈü¶ÔÕóÇ¿µÐÐÙÑÀÀû£¬°¢ÂüÎ÷°Â¼ÓÊ±ÈüµÄ½øÇò±£Ö¤¶·Å£Ê¿2-1¹ý¹Ø¡£¾öÈüÔÚ²®ÄÉÎÚ¾ÞÐÇ£¬Âí¶¡ÄÚË¹ÖÕ³¡Ç°¾øÉ±ËÕÁª£¬Î÷°àÑÀÔÚ¼ÒÃÅ¿ÚÅõÆðÅ·ÖÞ±­¡£\r\n\r\n','61.171.253.4','2007-12-03 10:04:55'),(3,'variant_date_to_timestamp','variant_date_to_timestampvariant_date_to_timestampvariant_date_to_timestamp fumction make data/time variant as unix time stamp','61.171.253.4','2007-12-03 10:07:58'),(4,'WELCOME TO TEMCO CONTOLS LTD','We manufacture HVAC controls and a range of HVAC sensors, relays, valves and thermostats at some of the best prices on the globe!\r\n','58.41.81.215','2007-12-03 20:48:33'),(5,'','','61.171.118.168','2007-12-04 07:01:40'),(6,'PHPÉú³É´øÓÐÑ©»¨±³¾°µÄÑéÖ¤Âë','<?session_start();?>\r\n<FORM METHOD=POST ACTION=\"\">\r\n<input type=text name=number maxlength=4><img src=\"YanZhengMa.php?act=init\">\r\n<INPUT TYPE=\"submit\" name=\"sub\">\r\n</FORM>\r\n<?\r\n//¼ìÑéÐ£ÑéÂë\r\nif(isset($HTTP_POST_VARS[\"sub\"])):\r\nif($HTTP_POST_VARS[\"number\"] != $HTTP_SESSION_VARS[login_check_number] || empty($HTTP_POST_VARS[\"number\"])){\r\n    echo \"Ð£ÑéÂë²»ÕýÈ·!\" ;\r\n}else{\r\n    echo\"ÑéÖ¤ÂëÍ¨¹ý£¡\";\r\n}\r\nendif;\r\nshow_source(\'test.php\');\r\n//ÒÔÉÏ±¾Ò³µÄÔ´Âë\r\n\r\n\r\n//ÒÔÏÂÊÇÉú³ÉÑéÖ¤ÂëµÄÔ´Âë\r\nshow_source(\'YanZhengMa.php\');\r\n?>\r\n<?php\r\nsession_start();\r\nsession_register(\"login_check_number\");\r\n//×òÍí¿´µ½ÁËchianrenÉÏµÄÑéÖ¤ÂëÐ§¹û£¬¾Í¿¼ÂÇÁËÒ»ÏÂ£¬ÓÃPHPµÄGD¿âÍê³ÉÁËÀàËÆ¹¦ÄÜ\r\n//ÏÈ³ÉÉú±³¾°£¬ÔÙ°ÑÉú³ÉµÄÑéÖ¤Âë·ÅÉÏÈ¥\r\n$img_height=120;    //ÏÈ¶¨ÒåÍ¼Æ¬µÄ³¤¡¢¿í\r\n$img_width=40;\r\nif($HTTP_GET_VARS[\"act\"]== \"init\"){\r\n    //srand(microtime() * 100000);//PHP420ºó£¬srand²»ÊÇ±ØÐëµÄ\r\n    for($Tmpa=0;$Tmpa<4;$Tmpa++){\r\n        $nmsg.=dechex(rand(0,15));\r\n    }//by sports98\r\n\r\n\r\n    $HTTP_SESSION_VARS[login_check_number] = $nmsg;\r\n\r\n    //$HTTP_SESSION_VARS[login_check_number] = strval(mt_rand(\"1111\",\"9999\"));    //Éú³É4Î»µÄËæ»úÊý£¬·ÅÈësessionÖÐ\r\n    //Ë­ÄÜ×öÏÂ²¹³ä£¬¿ÉÒÔÍ¬Ê±Éú³É×ÖÄ¸ºÍÊý×Ö°¡£¿£¿----ÓÉsports98Íê³ÉÁË\r\n\r\n    $aimg = imageCreate($img_height,$img_width);    //Éú³ÉÍ¼Æ¬\r\n    ImageColorAllocate($aimg, 255,255,255);            //Í¼Æ¬µ×É«£¬ImageColorAllocateµÚ1´Î¶¨ÒåÑÕÉ«PHP¾ÍÈÏÎªÊÇµ×É«ÁË\r\n    $black = ImageColorAllocate($aimg, 0,0,0);        //¶¨ÒåÐèÒªµÄºÚÉ«\r\n    ImageRectangle($aimg,0,0,$img_height-1,$img_width-1,$black);//ÏÈ³ÉÒ»ºÚÉ«µÄ¾ØÐÎ°ÑÍ¼Æ¬°üÎ§\r\n\r\n    //ÏÂÃæ¸ÃÉú³ÉÑ©»¨±³¾°ÁË£¬ÆäÊµ¾ÍÊÇÔÚÍ¼Æ¬ÉÏÉú³ÉÒ»Ð©·ûºÅ\r\n    for ($i=1; $i<=100; $i++) {    //ÏÈÓÃ100¸ö×ö²âÊÔ\r\n        imageString($aimg,1,mt_rand(1,$img_height),mt_rand(1,$img_width),\"*\",imageColorAllocate($aimg,mt_rand(200,255),mt_rand(200,255),mt_rand(200,255)));\r\n        //¹þ£¬¿´µ½ÁË°É£¬ÆäÊµÒ²²»ÊÇÑ©»¨£¬¾ÍÊÇÉú³É£ªºÅ¶øÒÑ¡£ÎªÁËÊ¹ËüÃÇ¿´ÆðÀ´\"ÔÓÂÒÎÞÕÂ¡¢5ÑÕ6É«\"£¬¾ÍµÃÔÚ1¸ö1¸öÉú³ÉËüÃÇµÄÊ±ºò£¬ÈÃËüÃÇµÄÎ»ÖÃ¡¢ÑÕÉ«£¬ÉõÖÁ´óÐ¡¶¼ÓÃËæ»úÊý£¬rand()»òmt_rand¶¼¿ÉÒÔÍê³É¡£\r\n    }\r\n\r\n    //ÉÏÃæÉú³ÉÁË±³¾°£¬ÏÖÔÚ¾Í¸Ã°ÑÒÑ¾­Éú³ÉµÄËæ»úÊý·ÅÉÏÀ´ÁË¡£µÀÀíºÍÉÏÃæ²î²»¶à£¬Ëæ»úÊý1¸ö1¸öµØ·Å£¬Í¬Ê±ÈÃËûÃÇµÄÎ»ÖÃ¡¢´óÐ¡¡¢ÑÕÉ«¶¼ÓÃ³ÉËæ»úÊý~~\r\n    //ÎªÁËÇø±ðÓÚ±³¾°£¬ÕâÀïµÄÑÕÉ«²»³¬¹ý200£¬ÉÏÃæµÄ²»Ð¡ÓÚ200\r\n    for ($i=0;$i<strlen($HTTP_SESSION_VARS[login_check_number]);$i++){\r\n        imageString($aimg, mt_rand(3,5),$i*$img_height/4+mt_rand(1,10),mt_rand(1,$img_width/2), $HTTP_SESSION_VARS[login_check_number][$i],imageColorAllocate($aimg,mt_rand(0,100),mt_rand(0,150),mt_rand(0,200)));\r\n    }\r\n    Header(\"Content-type: image/png\");    //¸æËßä¯ÀÀÆ÷£¬ÏÂÃæµÄÊý¾ÝÊÇÍ¼Æ¬£¬¶ø²»Òª°´ÎÄ×ÖÏÔÊ¾\r\n    ImagePng($aimg);                    //Éú³Épng¸ñÊ½¡£¡£¡£ºÙºÙÐ§¹ûÂùÏñ»ØÊÂµÄÂï¡£¡£¡£\r\n    ImageDestroy($aimg);\r\n}\r\n\r\n?> ','58.41.81.215','2007-12-04 20:56:35'),(7,'T3-8-13Relay','The T3-8-13Relay is an Analog Input & Relay Output Module with 8 Analog Input Channels & 13 Relay Output Channels on board.\r\n\r\nThe inputs can be configured to take 0-5V signals, 0-20mA signals, Thermistor temperature sensors, Dry Contact Closures, or high speed pulse inputs. The Ai8_R13 converts any analog signals into a 10-bit value between 0-1024.\r\n\r\nThe Relay Outputs are rated for 1Amp @ 24VAC and can be used to control various types of On/Off devices. Each Relay can be controlled through software or can be controlled at the device manually by using the built-in Hand/Off/Auto switches that are provided. Indicator LEDs for the inputs and outputs provide a visual indication of the current status of each point.\r\n\r\nThe Ai8_R13 can communicate with a higher level control system via Modbus485. The units are also accessible over Ethernet by using the Ai8_R13 BarioNet Gateway, which communicates with up to 8 of the modules concurrently and exposes all of the input values & allows control of the outputs via HTTP, TCP, or ModbusTCP. ','61.171.119.209','2007-12-05 18:51:47'),(8,'Tstat 5 Series','CPU based Zone Controller Wide variety of control strategies. NETWORK port for simple MODBUS communications, a real gem for integrators. Now with FLASH update over the network, 100% and highly customizable sequences. ','61.171.119.209','2007-12-05 18:52:16'),(9,'Differential air pressure switch ','Application This presure switch can be used to sense(differential) presure and flow of air in ducts and popes.Typical applications include: \r\nClogged filter detection. \r\nDetection of icing on air conditioning coils and initiation of defrost cycle \r\nAir proving in heading or ventilation ducts. \r\nmaximumair flow cpntroller for variable air volume systems \r\nBurner air control ','61.171.119.209','2007-12-05 18:52:47');
