CREATE TABLE `mobile_cart_checkouts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL COMMENT '用户ID',
  `checkout_token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结算令牌',
  `items_json` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '购物车商品JSON',
  `total_items` int(10) unsigned DEFAULT '0' COMMENT '商品种类数',
  `total_quantity` int(10) unsigned DEFAULT '0' COMMENT '商品总数量',
  `subtotal` decimal(10,2) NOT NULL COMMENT '商品小计',
  `shipping_fee` decimal(10,2) DEFAULT '0.00' COMMENT '运费',
  `discount_amount` decimal(10,2) DEFAULT '0.00' COMMENT '优惠金额',
  `tax_amount` decimal(10,2) DEFAULT '0.00' COMMENT '税费',
  `total_amount` decimal(10,2) NOT NULL COMMENT '应付总额',
  `address_snapshot` text COLLATE utf8mb4_unicode_ci COMMENT '地址快照',
  `status` enum('pending','processing','completed','cancelled','expired') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `expired_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '过期时间',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `checkout_token` (`checkout_token`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_checkout_token` (`checkout_token`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='移动端购物车结算会话表';
