  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP地址',
  `user_agent` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-Agent',
  `expires_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '过期时间',
  `used_at` timestamp NULL DEFAULT NULL COMMENT '使用时间（一次性使用标记）',
  `revoked_at` timestamp NULL DEFAULT NULL COMMENT '吊销时间',
