  `Extension` varchar(225) NOT NULL,
  `FirstName` varchar(128) NOT NULL COMMENT '姓',
  `LastName` varchar(128) NOT NULL COMMENT '名',
  `Email` varchar(128) NOT NULL COMMENT '邮箱地址',
  `Telephone` int(11) NOT NULL COMMENT '电话',
  `Fax` int(11) NOT NULL,
  `BillingAddress` varchar(128) NOT NULL,
  `BillingAddress2` varchar(128) NOT NULL,
  `BillingCity` varchar(128) NOT NULL,
  `BillingState` varchar(128) NOT NULL,
  `BillingZip` int(11) NOT NULL,
  `BillingCountry` varchar(128) NOT NULL,
  `ShippingCompany` varchar(128) NOT NULL,
  `ShippingAddress` varchar(128) NOT NULL,
  `ShippingAddress2` varchar(128) NOT NULL,
  `ShippingCity` varchar(128) NOT NULL,
  `ShippingState` varchar(128) NOT NULL,
  `ShippingZip` varchar(128) NOT NULL,
  `ShippingCountry` varchar(128) NOT NULL,
  `MailingList` varchar(128) NOT NULL,
  `CreateTime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
