INSERT INTO `website_text` VALUES (1,'search.php','Your Search Results  HVAC Products ','The results of your search are listed below. Click on any product for more information.','t'),(2,'specials.php','Sensor Equipment. USA  Online Specials','Our current online specials are listed below. Click on any product to find out more information and to order.\n','t'),(3,'shipping.php','Our Shipping and Handling Policies','You can enter a description of your shipping rates and terms, such as estimated time to delivery, etc.\r\n\r\nThis will be shown in a popup window when the customer clicks on \"View Shipping Rates\" when viewing their shopping cart or checking out.                                 ','t'),(4,'contact.php','Contact Us International HVAC Products Supplier','Use the contact form on this page to contact us with your comments, questions, or suggestions.\r\n\r\nYou can also reach us by telephone, FAX, or email.','t'),(5,'cart.php','Your Shopping Cart','<center>Your Shopping Cart Contains the Following Items:</center>','t'),(6,'index.php','Welcome to Toys HONGKONG','<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"10\" style=\"padding:0px;margin:0px;\">\n	<tr><td valign=\"top\">\nWelcome to our Toy Wonderland! We are a leading toy e-commerce platform based in Hong Kong, bringing you an exceptional experience with high-quality toys. We take pride in our carefully curated product line, offering top-notch toys at affordable prices, dedicated to providing your children with safe and creatively stimulating entertainment.\n\nHere, you will discover a wide range of toys, from educational playthings to imaginative dolls, all radiating joy and happiness. We collaborate with globally renowned toy manufacturers, ensuring that each product meets the strictest safety standards, providing worry-free playtime for your children.\n\nIn our toy warehouse, every item undergoes rigorous quality checks to guarantee the best play experience for your children. Whether for gifts or everyday shopping, we strive to make your shopping experience delightful and effortless.\n\nExplore our exciting world, uncovering those unique treasures crafted for children. On our website, high quality blends seamlessly with budget-friendly prices, delivering smiles and endless hours of play for your little ones.\n</td>\n\n	</tr>\n</table>\n<hr style=\"size:2xp;color:#E8E8E8;\">\n\n<font style=\"family:arial;font-size:1.6em;color:#8e8e8e;font-weight:800;\">Featured Products:</font>\n<hr style=\"size:2xp;color:#E8E8E8;\">\n\n<div align=\"center\">','h'),(7,'checkout/index.php','IBS-Controls ltd Check Out','Check out using the form below.  \r\n\r\n','t'),(8,'checkout/payment.php','Purchase Confirmation','Please confirm your order and billing information below. When finshed, click \"<b>Proceed with Purchase</b>\" at the bottom of the screen to be taken to PayPal\'s Website to complete the ordering process.  You can use your Visa, MasterCard, Discover, American Express or your checking account to pay for your order through PayPal.  You can press the \"<b>Make Changes</b>\" button to go back to the previous page and make any desired changes to your order.','t'),(9,'checkout/payment_manual.php','Your Order has been saved','Thanks for your order!  Please use the link below to print a receipt.  \r\n\r\nYour order will not be processed until we have received your check or money order in the mail.  \r\n\r\nPlease note that checks may add up to 7 business days to the time of delivery.','t'),(12,'checkout/payment_authnet_success.php','Your Credit Card Order Has Been Processed','Thanks for your order!  Please use the link below to print a receipt.  ','t'),(13,'checkout/payment_authnet_failure.php','Errors Processing Your Credit Card','We\'re sorry, but your credit card information was not accepted.  Please re-check the credit card type, number, and expiration date you entered.','t'),(14,'checkout/payment_paypal_complete.php','Your PayPal Order Has Been Processed','Thanks for your order!  Please use the link below to print a receipt.  ','t'),(15,'email/order_authnet.php','Thanks for Your Order from Sensor Equipment Ltd.','Hello,\n\nYour order has been entered, we will contact you shortly regarding fulfillment. \n\nThanks for your business,\n\nSensor Equipemnt Ltd. USA\n4416 South Parkside Court\nSpokane, Washington 99223\nUS\n\nTel:(214) 800-4562\nFax:(206) 888-8888\nsales@sensorequipment.com','t'),(16,'email/order_manual.php','Thanks for Your Order from Sensor Equipment Ltd. USA','Thanks for your order.  We have saved your order information, but we will not be able to begin any final work or ship your order until your payment arrives.  Please make payment using any of the following methods:\n\nMail in a printed copy of your invoice to:\nSensor Equipment Ltd. USA\n4416 South Parkside Court\nSpokane, Washington 99223\nUS\n\nTel:(452) 542-6564\nFax:(656) 456-6588\n\nYou can also call us directly and pay for your order using your Visa, Mastercard, or Discover.  Please be sure to have your order number available when you call.\n\n\nThanks Again,\n\nTemcocontrols Ltd. USA\nsales@temcocontrols.com','t'),(17,'checkout/payment_cc_failure.php','Errors Processing Your Credit Card','We\'re sorry, but your credit card information was not accepted.  Please re-check the credit card type, number, and expiration date you entered.','t'),(18,'checkout/payment_cc_success.php','Your Credit Card Order Has Been Processed','Thanks for your order!  Please use the link below to print a receipt.  ','t'),(19,'email/order_cc.php','Thanks for Your Order from COMPANY','Thanks for your order.  We have saved your order information, but we will not be able to begin any final work or ship your order until your payment arrives.  Please make payment using any of the following methods:\r\n\r\nMail in a printed copy of your invoice to:\r\nCOMPANY NAME\r\nAddress Line 1\r\nAddress Line 2\r\nCity, State, Zip\r\n\r\nYou can also call us directly and pay for your order using your Visa, Mastercard, or Discover.  Please be sure to have your order number available when you call.\r\n\r\nOur toll-free payment line is:\r\n(800)123-4567\r\n(8-5 EST, M-F)\r\n\r\nThanks Again,\r\n\r\nCOMPANY\r\nEMAIL','t'),(20,'admin/index.php','Toys HONGKONG','<div align=\"center\">\n<img src=\"/images/site/images1.jpg\" alt=\"\" width=\"309\" height=\"163\" border=\"0\" />\n	<big><big><b>Welcome to andyweiren ltd Administrative Area!</b></big></big><br>\n	<small><b>Powered by <a href=\"http://www.andyweiren.com\"></a><a href=\"http://www.andyweiren.com\" target=\"_blank\">xx.andyweiren.com \n	</a></b></small></div>\n<p><big>Use the menu choices to your left to manage your products, categories, orders and customers, edit the text on the various pages of your website, update your company preferences, set shipping &amp; tax options, or to access any other custom modules you may have added to your website.</big></p>\n<p><font size=\"4\">This </font><big>\nControl Panel  is where you will be able to view your website statistics, edit your website keywords and description, and submit any necessary maintenance requests, among many other options.</big></p>','t'),(21,'checkout/popup_cvv.php','CVV2 FAQ','<div align=\"left\">\r\n<ol>\r\n	<li><b>What is CVV2?</b><br>\r\n	CVV2 is an authentication mechanism created by card companies to help reduce fraud with online transactions. It requires the card holder to have the card physically in hand in order to enter three or four digits found printed on the card itself.<br>\r\n	<br></li>\r\n	<li>\r\n		<b>Where do I find the numbers?</b><br>\r\n		On Visa, MasterCard and Discover credit cards, the number is located on the back of the card in the signature area:<br>\r\n		<img hspace=\"20\" vspace=\"10\" src=\"/common/cart4/images/cvv2_visa.gif\" width=\"215\" height=\"103\"><br>\r\n		On American Express cards, the number is located on the front of the card, just above the card number, usually on the right:<br>\r\n		<img alt=\"AmEx CVV2\" hspace=\"20\" src=\"/common/cart4/images/cvv2_amex.gif\" width=\"248\" height=\"129\"><br>\r\n		Diner\'s Club and some older credit cards may not have the CVV2 codes.<br>\r\n		<br>\r\n	</li>\r\n	<li><b>My card doesn\'t have CVV2. What do I do?</b><br>\r\n	If your card does not have CVV2 numbers, leave this entry blank. However, this information helps us process your Credit Card order faster.<br>\r\n	<br></li>\r\n	<li><b>Why are you requiring this?</b><br>\r\n	Credit card fraud is on the rise on the Internet. Requiring CVV2 codes is just one more action we take to ensure that our customers\' security is protected.</li>\r\n</ol>\r\n</div>','h'),(25,'email/reset_password.php','Password Recovery','Hello $var->fullname,\n\nYour password has been reset, your new login \ninformation is:\n\n     username: $var->username\n     password: $var->newpassword\n\nIt is highly recommended that you log in and change your \npassword as soon as possible.\n\nThank you for using our website!\n\nSincerely, \n\nSupport \n$var->support\n$var->URL','t'),(31,'company.php','Shop by Company','All of our companies that we carry products for are shown below.','t'),(32,'links.php','HVAC Products Links','','t');
